704 |     fn decode_miniblock_chunk(
705 |         &self,
706 |         buf: &LanceBuffer,
707 |         items_in_chunk: u64,
708 |     ) -> Result<DecodedMiniBlockChunk> {
709 |         let mut offset = 0;
710 |         let num_levels = u16::from_le_bytes([buf[offset], buf[offset + 1]]);
711 |         offset += 2;
712 | 
713 |         let rep_size = if self.rep_decompressor.is_some() {
714 |             let rep_size = u16::from_le_bytes([buf[offset], buf[offset + 1]]);
715 |             offset += 2;
716 |             Some(rep_size)
717 |         } else {
718 |             None
719 |         };
720 |         let def_size = if self.def_decompressor.is_some() {
721 |             let def_size = u16::from_le_bytes([buf[offset], buf[offset + 1]]);
722 |             offset += 2;
723 |             Some(def_size)
724 |         } else {
725 |             None
726 |         };
727 | 
728 |         let buffer_sizes = if self.has_large_chunk {
729 |             Self::read_buffer_sizes::<true>(buf, &mut offset, self.num_buffers)
730 |         } else {
731 |             Self::read_buffer_sizes::<false>(buf, &mut offset, self.num_buffers)
732 |         };
733 | 
734 |         offset += pad_bytes::<MINIBLOCK_ALIGNMENT>(offset);
735 | 
736 |         let rep = rep_size.map(|rep_size| {
737 |             let rep = buf.slice_with_length(offset, rep_size as usize);
738 |             offset += rep_size as usize;
739 |             offset += pad_bytes::<MINIBLOCK_ALIGNMENT>(offset);
740 |             rep
741 |         });
742 | 
743 |         let def = def_size.map(|def_size| {
744 |             let def = buf.slice_with_length(offset, def_size as usize);
745 |             offset += def_size as usize;
746 |             offset += pad_bytes::<MINIBLOCK_ALIGNMENT>(offset);
747 |             def
748 |         });
749 | 
750 |         let num_levels = Self::resolve_num_levels(
751 |             self.rep_decompressor.as_deref(),
752 |             rep.as_ref(),
753 |             self.def_decompressor.as_deref(),
754 |             def.as_ref(),
755 |             num_levels,
756 |         )?;
757 | 
758 |         let buffers = buffer_sizes
759 |             .into_iter()
760 |             .map(|buf_size| {
761 |                 let buf = buf.slice_with_length(offset, buf_size as usize);
762 |                 offset += buf_size as usize;
763 |                 offset += pad_bytes::<MINIBLOCK_ALIGNMENT>(offset);
764 |                 buf
765 |             })
766 |             .collect::<Vec<_>>();
767 | 
768 |         let values = self
769 |             .value_decompressor
770 |             .decompress(buffers, items_in_chunk)?;
771 | 
772 |         let rep = rep
773 |             .map(|rep| {
774 |                 Self::decode_levels(
775 |                     self.rep_decompressor.as_ref().unwrap().as_ref(),
776 |                     rep,
777 |                     num_levels,
778 |                 )
779 |             })
780 |             .transpose()?;
781 |         let def = def
782 |             .map(|def| {
783 |                 Self::decode_levels(
784 |                     self.def_decompressor.as_ref().unwrap().as_ref(),
785 |                     def,
786 |                     num_levels,
787 |                 )
788 |             })
789 |             .transpose()?;
790 | 
791 |         if let (Some(rep), Some(def)) = (&rep, &def)
792 |             && rep.len() != def.len()
793 |         {
794 |             return Err(Error::invalid_input_source(
795 |                 format!(
796 |                     "miniblock structural streams decoded different level counts: repetition {}, definition {}",
797 |                     rep.len(),
798 |                     def.len()
799 |                 )
800 |                 .into(),
801 |             ));
802 |         }
803 | 
804 |         Ok(DecodedMiniBlockChunk { rep, def, values })
805 |     }
806 | }
