2669 | fn analyze_value_counts(words: &Words, items_in_page: u64) -> Result<FlatValueCounts> {
2670 |     let num_chunks = words.len();
2671 |     let logs = words.iter().map(|w| (w & 0x0F) as u8).collect::<Vec<_>>();
2672 |     let mut counted = 0u64;
2673 |     for (chunk_index, &log) in logs.iter().take(num_chunks.saturating_sub(1)).enumerate() {
2674 |         if log == 0 {
2675 |             return Err(Error::corrupt_file_named(
2676 |                 "miniblock_metadata",
2677 |                 format!(
2678 |                     "non-final chunk {chunk_index} of {num_chunks} has invalid log_num_values=0"
2679 |                 ),
2680 |             ));
2681 |         }
2682 |         counted = counted.checked_add(1u64 << log).ok_or_else(|| {
2683 |             Error::corrupt_file_named(
2684 |                 "miniblock_metadata",
2685 |                 format!(
2686 |                     "value count overflow at chunk {chunk_index}: counted_values={counted}, \
2687 |                      log_num_values={log}, items_in_page={items_in_page}"
2688 |                 ),
2689 |             )
2690 |         })?;
2691 |     }
2692 |     let last_chunk_values = items_in_page.checked_sub(counted).ok_or_else(|| {
2693 |         Error::corrupt_file_named(
2694 |             "miniblock_metadata",
2695 |             format!(
2696 |                 "non-final chunks account for counted_values={counted}, exceeding \
2697 |                  items_in_page={items_in_page}"
2698 |             ),
2699 |         )
2700 |     })?;
2701 |     if let Some(&last_log) = logs.last()
2702 |         && last_log != 0
2703 |         && (1u64 << last_log) != last_chunk_values
2704 |     {
2705 |         return Err(Error::corrupt_file_named(
2706 |             "miniblock_metadata",
2707 |             format!(
2708 |                 "final chunk log_num_values={last_log} does not match \
2709 |                  last_chunk_values={last_chunk_values}: counted_values={counted}, \
2710 |                  items_in_page={items_in_page}"
2711 |             ),
2712 |         ));
2713 |     }
2714 |     let uniform = num_chunks <= 1 || logs[..num_chunks - 1].iter().all(|&log| log == logs[0]);
2715 |     // A single-chunk page has no "non-last" chunk to derive a stride from; use the
2716 |     // page item count (min 1 so it stays a valid divisor in `find_chunk`).
2717 |     let values_per_chunk = if num_chunks <= 1 {
2718 |         items_in_page.max(1)
2719 |     } else {
2720 |         1u64 << logs[0]
2721 |     };
2722 |     Ok(FlatValueCounts {
2723 |         logs,
2724 |         uniform,
2725 |         values_per_chunk,
2726 |         last_chunk_values,
2727 |     })
2728 | }
