2730 | /// Iterator over per-chunk value counts for a non-uniform flat page.  Non-last
2731 | /// chunks yield `1 << log`; the last yields the validated remaining item count.
2732 | fn flat_value_counts_iter(logs: &[u8], last_chunk_values: u64) -> impl Iterator<Item = u64> + '_ {
2733 |     let num_chunks = logs.len();
2734 |     (0..num_chunks).map(move |i| {
2735 |         if i + 1 < num_chunks {
2736 |             1u64 << logs[i]
2737 |         } else {
2738 |             last_chunk_values
2739 |         }
2740 |     })
2741 | }
