2743 | /// Builds the compact per-chunk index from the metadata words and, for nested
2744 | /// pages, the raw repetition-index bytes.  The row axis is picked by page shape:
2745 | /// `UniformFlat` when all non-last chunks share a value count (fixed-width /
2746 | /// bitpacking), `Flat` for non-uniform flat pages (RLE / FSST), else `Nested`.
2747 | fn build_chunk_index(
2748 |     words: &Words,
2749 |     items_in_page: u64,
2750 |     base: u64,
2751 |     data_buf_size: u64,
2752 |     rep_index_bytes: Option<&[u8]>,
2753 |     repetition_index_depth: u16,
2754 | ) -> Result<MiniBlockChunkIndex> {
2755 |     let num_chunks = words.len();
2756 |     // Validate item counts before byte sizes because both share a metadata word,
2757 |     // and an invalid count must not reach the final-chunk subtraction.
2758 |     let value_counts = analyze_value_counts(words, items_in_page)?;
2759 | 
2760 |     // Each chunk stores `(divided_bytes + 1) * MINIBLOCK_ALIGNMENT` bytes, so the
2761 |     // deltas are the chunk sizes and their grand total is the data buffer size.
2762 |     let byte_starts = PrefixSums::from_deltas(
2763 |         words
2764 |             .iter()
2765 |             .map(|word| ((word >> 4) as u64 + 1) * MINIBLOCK_ALIGNMENT as u64),
2766 |         num_chunks,
2767 |         data_buf_size,
2768 |     );
2769 | 
2770 |     // Nested pages track rows via the repetition index and keep leaf item counts
2771 |     // separately; flat pages have row == value index, so value counts are rows.
2772 |     let rows = if let Some(rep_index_data) = rep_index_bytes {
2773 |         assert!(rep_index_data.len() % 8 == 0);
2774 |         let stride = repetition_index_depth as usize + 1;
2775 |         let (row_starts, has_trailer) = parse_nested_rep(rep_index_data, stride);
2776 |         let item_counts = if value_counts.uniform {
2777 |             ItemCounts::Uniform {
2778 |                 values_per_chunk: value_counts.values_per_chunk,
2779 |                 last_chunk_values: value_counts.last_chunk_values,
2780 |             }

5751 |     fn serialize_miniblocks(
5752 |         miniblocks: MiniBlockCompressed,
5753 |         rep: Option<Vec<CompressedLevelsChunk>>,
5754 |         def: Option<Vec<CompressedLevelsChunk>>,
5755 |         miniblock_chunk_size: MiniblockChunkSize,
5756 |     ) -> Result<SerializedMiniBlockPage> {
5757 |         let bytes_rep = rep
5758 |             .as_ref()
5759 |             .map(|rep| rep.iter().map(|r| r.data.len()).sum::<usize>())
5760 |             .unwrap_or(0);
5761 |         let bytes_def = def
5762 |             .as_ref()
5763 |             .map(|def| def.iter().map(|d| d.data.len()).sum::<usize>())
5764 |             .unwrap_or(0);
5765 |         let bytes_data = miniblocks.data.iter().map(|d| d.len()).sum::<usize>();
5766 |         let mut num_buffers = miniblocks.data.len();
5767 |         if rep.is_some() {
5768 |             num_buffers += 1;
5769 |         }
5770 |         if def.is_some() {
5771 |             num_buffers += 1;
5772 |         }
5773 |         // 2 bytes for the length of each buffer and up to 7 bytes of padding per buffer
5774 |         let max_extra = 9 * num_buffers;
5775 |         let mut data_buffer = Vec::with_capacity(bytes_rep + bytes_def + bytes_data + max_extra);
5776 |         let chunk_size_bytes = match miniblock_chunk_size {
5777 |             MiniblockChunkSize::U16 => 2,
5778 |             MiniblockChunkSize::U32 => 4,
5779 |         };
5780 |         let mut meta_buffer = Vec::with_capacity(miniblocks.chunks.len() * chunk_size_bytes);
5781 | 
5782 |         let mut rep_iter = rep.map(|r| r.into_iter());
5783 |         let mut def_iter = def.map(|d| d.into_iter());
5784 | 
5785 |         let mut buffer_offsets = vec![0; miniblocks.data.len()];
5786 |         for chunk in miniblocks.chunks {
5787 |             let start_pos = data_buffer.len();
5788 |             // Start of chunk should be aligned
5789 |             debug_assert_eq!(start_pos % MINIBLOCK_ALIGNMENT, 0);
5790 | 
5791 |             let rep = rep_iter.as_mut().map(|r| r.next().unwrap());
5792 |             let def = def_iter.as_mut().map(|d| d.next().unwrap());
5793 | 
5794 |             // Write the number of levels, or 0 if there is no rep/def
5795 |             let num_levels = rep
5796 |                 .as_ref()
5797 |                 .map(|r| r.num_levels)
5798 |                 .unwrap_or(def.as_ref().map(|d| d.num_levels).unwrap_or(0));
5799 |             data_buffer.extend_from_slice(&num_levels.to_le_bytes());
5800 | 
5801 |             // Write the buffer lengths
5802 |             if let Some(rep) = rep.as_ref() {
5803 |                 let bytes_rep = u16::try_from(rep.data.len()).map_err(|_| {
5804 |                     Error::internal(format!(
5805 |                         "Repetition buffer size ({} bytes) too large",
5806 |                         rep.data.len()
5807 |                     ))
5808 |                 })?;
5809 |                 data_buffer.extend_from_slice(&bytes_rep.to_le_bytes());
5810 |             }
5811 |             if let Some(def) = def.as_ref() {
5812 |                 let bytes_def = u16::try_from(def.data.len()).map_err(|_| {
5813 |                     Error::internal(format!(
5814 |                         "Definition buffer size ({} bytes) too large",
5815 |                         def.data.len()
5816 |                     ))
5817 |                 })?;
5818 |                 data_buffer.extend_from_slice(&bytes_def.to_le_bytes());
5819 |             }
5820 | 
5821 |             if miniblock_chunk_size == MiniblockChunkSize::U32 {
5822 |                 for &buffer_size in &chunk.buffer_sizes {
5823 |                     data_buffer.extend_from_slice(&buffer_size.to_le_bytes());
5824 |                 }
5825 |             } else {
5826 |                 for &buffer_size in &chunk.buffer_sizes {
5827 |                     let buffer_size = u16::try_from(buffer_size).map_err(|_| {
5828 |                         Error::internal(format!(
5829 |                             "Mini-block buffer size ({} bytes) too large for 16-bit metadata",
5830 |                             buffer_size
5831 |                         ))
5832 |                     })?;
5833 |                     data_buffer.extend_from_slice(&buffer_size.to_le_bytes());
5834 |                 }
5835 |             }
5836 | 
5837 |             // Pad
5838 |             let add_padding = |data_buffer: &mut Vec<u8>| {
5839 |                 let pad = pad_bytes::<MINIBLOCK_ALIGNMENT>(data_buffer.len());
5840 |                 data_buffer.extend(iter::repeat_n(FILL_BYTE, pad));
5841 |             };
5842 |             add_padding(&mut data_buffer);
5843 | 
5844 |             // Write the buffers themselves
5845 |             if let Some(rep) = rep.as_ref() {
5846 |                 data_buffer.extend_from_slice(&rep.data);
5847 |                 add_padding(&mut data_buffer);
5848 |             }
5849 |             if let Some(def) = def.as_ref() {
5850 |                 data_buffer.extend_from_slice(&def.data);
5851 |                 add_padding(&mut data_buffer);
5852 |             }
5853 |             for (buffer_size, (buffer, buffer_offset)) in chunk
5854 |                 .buffer_sizes
5855 |                 .iter()
5856 |                 .zip(miniblocks.data.iter().zip(buffer_offsets.iter_mut()))
5857 |             {
5858 |                 let start = *buffer_offset;
5859 |                 let end = start + *buffer_size as usize;
5860 |                 *buffer_offset += *buffer_size as usize;
5861 |                 data_buffer.extend_from_slice(&buffer[start..end]);
5862 |                 add_padding(&mut data_buffer);
5863 |             }
5864 | 
5865 |             let chunk_bytes = data_buffer.len() - start_pos;
5866 |             let max_chunk_size = match miniblock_chunk_size {
5867 |                 MiniblockChunkSize::U16 => 32 * 1024,
5868 |                 MiniblockChunkSize::U32 => 1_u64 << 31,
5869 |             };
5870 |             if chunk_bytes == 0 || chunk_bytes as u64 > max_chunk_size {
5871 |                 return Err(Error::internal(format!(
5872 |                     "Mini-block chunk size {} bytes exceeds the {} byte metadata limit",
5873 |                     chunk_bytes, max_chunk_size
5874 |                 )));
5875 |             }
5876 |             if chunk_bytes % MINIBLOCK_ALIGNMENT != 0 {
5877 |                 return Err(Error::internal(format!(
5878 |                     "Mini-block chunk size {} bytes is not aligned to {} bytes",
5879 |                     chunk_bytes, MINIBLOCK_ALIGNMENT
5880 |                 )));
5881 |             }
5882 |             if chunk.log_num_values > 15 {
5883 |                 return Err(Error::internal(format!(
5884 |                     "Mini-block log_num_values {} exceeds the 4-bit metadata limit",
5885 |                     chunk.log_num_values
5886 |                 )));
5887 |             }
5888 |             // We subtract 1 here from chunk_bytes because we want to be able to express
5889 |             // a size of 32KiB and not (32Ki - 8)B which is what we'd get otherwise with
5890 |             // 0xFFF
5891 |             let divided_bytes = chunk_bytes / MINIBLOCK_ALIGNMENT;
5892 |             let divided_bytes_minus_one = (divided_bytes - 1) as u64;
5893 | 
5894 |             let metadata = (divided_bytes_minus_one << 4) | chunk.log_num_values as u64;
5895 |             if miniblock_chunk_size == MiniblockChunkSize::U32 {
5896 |                 meta_buffer.extend_from_slice(&(metadata as u32).to_le_bytes());
5897 |             } else {
5898 |                 meta_buffer.extend_from_slice(&(metadata as u16).to_le_bytes());
5899 |             }
5900 |         }
5901 | 
5902 |         let data_buffer = LanceBuffer::from(data_buffer);
5903 |         let metadata_buffer = LanceBuffer::from(meta_buffer);
5904 | 
5905 |         Ok(SerializedMiniBlockPage {
5906 |             num_buffers: miniblocks.data.len() as u64,
5907 |             data: data_buffer,
5908 |             metadata: metadata_buffer,
5909 |         })
5910 |     }
