5912 |     /// Compresses a buffer of levels into chunks
5913 |     ///
5914 |     /// If these are repetition levels then we also calculate the repetition index here (that
5915 |     /// is the third return value)
5916 |     fn compress_levels(
5917 |         mut levels: RepDefSlicer<'_>,
5918 |         num_elements: u64,
5919 |         compression_strategy: &dyn CompressionStrategy,
5920 |         chunks: &[MiniBlockChunk],
5921 |         // This will be 0 if we are compressing def levels
5922 |         max_rep: u16,
5923 |     ) -> Result<CompressedLevels> {
5924 |         let mut rep_index = if max_rep > 0 {
5925 |             Vec::with_capacity(chunks.len())
5926 |         } else {
5927 |             vec![]
5928 |         };
5929 |         // Make the levels into a FixedWidth data block
5930 |         let num_levels = levels.num_levels() as u64;
5931 |         let levels_buf = levels.all_levels().clone();
5932 | 
5933 |         let mut fixed_width_block = FixedWidthDataBlock {
5934 |             data: levels_buf,
5935 |             bits_per_value: 16,
5936 |             num_values: num_levels,
5937 |             block_info: BlockInfo::new(),
5938 |         };
5939 |         // Compute statistics to enable optimal compression for rep/def levels
5940 |         fixed_width_block.compute_stat();
5941 | 
5942 |         let levels_block = DataBlock::FixedWidth(fixed_width_block);
5943 |         let levels_field = Field::new_arrow("", DataType::UInt16, false)?;
5944 |         // Pick a block compressor
5945 |         let compressor =
5946 |             compression_strategy.create_block_compressor(&levels_field, &levels_block)?;
5947 |         let mut compressor_desc = None;
5948 |         // Compress blocks of levels (sized according to the chunks)
5949 |         let mut level_chunks = Vec::with_capacity(chunks.len());
5950 |         let mut values_counter = 0;
5951 |         for (chunk_idx, chunk) in chunks.iter().enumerate() {
5952 |             let chunk_num_values = chunk.num_values(values_counter, num_elements);
5953 |             debug_assert!(chunk_num_values > 0);
5954 |             values_counter += chunk_num_values;
5955 |             let chunk_levels = if chunk_idx < chunks.len() - 1 {
5956 |                 levels.slice_next(chunk_num_values as usize)
5957 |             } else {
5958 |                 levels.slice_rest()
5959 |             };
5960 |             let num_chunk_levels = (chunk_levels.len() / 2) as u64;
5961 |             if max_rep > 0 {
5962 |                 // If max_rep > 0 then we are working with rep levels and we need
5963 |                 // to calculate the repetition index.  The repetition index for a
5964 |                 // chunk is currently 2 values (in the future it may be more).
5965 |                 //
5966 |                 // The first value is the number of rows that _finish_ in the
5967 |                 // chunk.
5968 |                 //
5969 |                 // The second value is the number of "leftovers" after the last
5970 |                 // finished row in the chunk.
5971 |                 let rep_values = chunk_levels.borrow_to_typed_slice::<u16>();
5972 |                 let rep_values = rep_values.as_ref();
5973 | 
5974 |                 // We skip 1 here because a max_rep at spot 0 doesn't count as a finished list (we
5975 |                 // will count it in the previous chunk)
5976 |                 let mut num_rows = rep_values.iter().skip(1).filter(|v| **v == max_rep).count();
5977 |                 let num_leftovers = if chunk_idx < chunks.len() - 1 {
5978 |                     rep_values
5979 |                         .iter()
5980 |                         .rev()
5981 |                         .position(|v| *v == max_rep)
5982 |                         // # of leftovers includes the max_rep spot
5983 |                         .map(|pos| pos + 1)
5984 |                         .unwrap_or(rep_values.len())
5985 |                 } else {
5986 |                     // Last chunk can't have leftovers
5987 |                     0
5988 |                 };
5989 | 
5990 |                 if chunk_idx != 0 && rep_values.first() == Some(&max_rep) {
5991 |                     // This chunk starts with a new row and so, if we thought we had leftovers
5992 |                     // in the previous chunk, we were mistaken
5993 |                     // TODO: Can use unchecked here
5994 |                     let rep_len = rep_index.len();
5995 |                     if rep_index[rep_len - 1] != 0 {
5996 |                         // We thought we had leftovers but that was actually a full row
5997 |                         rep_index[rep_len - 2] += 1;
5998 |                         rep_index[rep_len - 1] = 0;
5999 |                     }
6000 |                 }
6001 | 
6002 |                 if chunk_idx == chunks.len() - 1 {
6003 |                     // The final list
6004 |                     num_rows += 1;
6005 |                 }
6006 |                 rep_index.push(num_rows as u64);
6007 |                 rep_index.push(num_leftovers as u64);
6008 |             }
6009 |             let mut chunk_fixed_width = FixedWidthDataBlock {
6010 |                 data: chunk_levels,
6011 |                 bits_per_value: 16,
6012 |                 num_values: num_chunk_levels,
6013 |                 block_info: BlockInfo::new(),
6014 |             };
6015 |             chunk_fixed_width.compute_stat();
6016 |             let chunk_levels_block = DataBlock::FixedWidth(chunk_fixed_width);
6017 |             let (compressed_levels, chunk_compressor_desc) =
6018 |                 compressor.compress(chunk_levels_block)?;
6019 |             if let Some(compressor_desc) = compressor_desc.as_ref() {
6020 |                 if compressor_desc != &chunk_compressor_desc {
6021 |                     return Err(Error::internal(
6022 |                         "Rep/def block compressor changed encoding between chunks".to_string(),
6023 |                     ));
6024 |                 }
6025 |             } else {
6026 |                 compressor_desc = Some(chunk_compressor_desc);
6027 |             }
6028 |             let compressed_levels = compressed_levels.ok_or_else(|| {
6029 |                 Error::internal(
6030 |                     "Rep/def block compressor selected a metadata-only codec".to_string(),
6031 |                 )
6032 |             })?;
6033 |             let num_levels = u16::try_from(num_chunk_levels).map_err(|_| {
6034 |                 Error::invalid_input_source(
6035 |                     format!(
6036 |                         "Mini-block cannot encode {} rep/def levels in one chunk. \
6037 |                          This usually means a top-level row contains too much nested structure \
6038 |                          for the current layout.",
6039 |                         num_chunk_levels
6040 |                     )
6041 |                     .into(),
6042 |                 )
6043 |             })?;
6044 |             level_chunks.push(CompressedLevelsChunk {
6045 |                 data: compressed_levels,
6046 |                 num_levels,
6047 |             });
6048 |         }
6049 |         debug_assert_eq!(levels.num_levels_remaining(), 0);
6050 |         let rep_index = if rep_index.is_empty() {
6051 |             None
6052 |         } else {
6053 |             Some(LanceBuffer::reinterpret_vec(rep_index))
6054 |         };
6055 |         Ok(CompressedLevels {
6056 |             data: level_chunks,
6057 |             compression: compressor_desc.ok_or_else(|| {
6058 |                 Error::internal("Rep/def compression produced no chunks".to_string())
6059 |             })?,
6060 |             rep_index,
6061 |         })
6062 |     }
