6396 |     fn encode_miniblock(
6397 |         column_idx: u32,
6398 |         field: &Field,
6399 |         compression_strategy: &dyn CompressionStrategy,
6400 |         data: DataBlock,
6401 |         repdef: crate::repdef::SerializedRepDefs,
6402 |         row_number: u64,
6403 |         dictionary_data: Option<DataBlock>,
6404 |         num_rows: u64,
6405 |         miniblock_chunk_size: MiniblockChunkSize,
6406 |     ) -> Result<EncodedPage> {
6407 |         if let DataBlock::AllNull(_null_block) = data {
6408 |             // We should not be using mini-block for all-null.  There are other structural
6409 |             // encodings for that.
6410 |             unreachable!()
6411 |         }
6412 | 
6413 |         let num_items = data.num_values();
6414 | 
6415 |         let compressor = compression_strategy.create_miniblock_compressor(field, &data)?;
6416 |         let common_chunk_buffers =
6417 |             u64::from(repdef.rep_slicer().is_some()) + u64::from(repdef.def_slicer().is_some());
6418 |         let support_large_chunk = miniblock_chunk_size == MiniblockChunkSize::U32;
6419 |         let compression_context =
6420 |             MiniBlockCompressionContext::new(common_chunk_buffers, support_large_chunk, true);
6421 |         let (compressed_data, value_encoding) = compressor.compress(compression_context, data)?;
6422 | 
6423 |         let max_rep = repdef.def_meaning.iter().filter(|l| l.is_list()).count() as u16;
6424 | 
6425 |         let mut compressed_rep = repdef
6426 |             .rep_slicer()
6427 |             .map(|rep_slicer| {
6428 |                 Self::compress_levels(
6429 |                     rep_slicer,
6430 |                     num_items,
6431 |                     compression_strategy,
6432 |                     &compressed_data.chunks,
6433 |                     max_rep,
6434 |                 )
6435 |             })
6436 |             .transpose()?;
6437 | 
6438 |         let (rep_index, rep_index_depth) =
6439 |             match compressed_rep.as_mut().and_then(|cr| cr.rep_index.as_mut()) {
6440 |                 Some(rep_index) => (Some(rep_index.clone()), 1),
6441 |                 None => (None, 0),
6442 |             };
6443 | 
6444 |         let mut compressed_def = repdef
6445 |             .def_slicer()
6446 |             .map(|def_slicer| {
6447 |                 Self::compress_levels(
6448 |                     def_slicer,
6449 |                     num_items,
6450 |                     compression_strategy,
6451 |                     &compressed_data.chunks,
6452 |                     /*max_rep=*/ 0,
6453 |                 )
6454 |             })
6455 |             .transpose()?;
6456 | 
6457 |         // TODO: Parquet sparsely encodes values here.  We could do the same but
6458 |         // then we won't have log2 values per chunk.  This means more metadata
6459 |         // and potentially more decoder asymmetry.  However, it may be worth
6460 |         // investigating at some point
6461 | 
6462 |         let rep_data = compressed_rep
6463 |             .as_mut()
6464 |             .map(|cr| std::mem::take(&mut cr.data));
6465 |         let def_data = compressed_def
6466 |             .as_mut()
6467 |             .map(|cd| std::mem::take(&mut cd.data));
6468 | 
6469 |         let serialized =
6470 |             Self::serialize_miniblocks(compressed_data, rep_data, def_data, miniblock_chunk_size)?;
6471 |         let has_large_chunk = miniblock_chunk_size == MiniblockChunkSize::U32;
6472 | 
6473 |         // Metadata, Data, Dictionary, (maybe) Repetition Index
6474 |         let mut data = Vec::with_capacity(4);
6475 |         data.push(serialized.metadata);
6476 |         data.push(serialized.data);
6477 | 
6478 |         if let Some(dictionary_data) = dictionary_data {
6479 |             let num_dictionary_items = dictionary_data.num_values();
6480 |             let dict_values_field = Self::build_dict_values_compressor_field(field)?;
6481 | 
6482 |             let (dictionary_buffer, dictionary_encoding) =
6483 |                 compress_required_block(compression_strategy, &dict_values_field, dictionary_data)?;
6484 | 
6485 |             data.push(dictionary_buffer);
6486 |             if let Some(rep_index) = rep_index {
6487 |                 data.push(rep_index);
6488 |             }
6489 | 
6490 |             let description = ProtobufUtils21::miniblock_layout(
6491 |                 compressed_rep.map(|cr| cr.compression),
6492 |                 compressed_def.map(|cd| cd.compression),
6493 |                 value_encoding,
6494 |                 rep_index_depth,
6495 |                 serialized.num_buffers,
6496 |                 Some((dictionary_encoding, num_dictionary_items)),
6497 |                 &repdef.def_meaning,
6498 |                 num_items,
6499 |                 has_large_chunk,
6500 |             );
6501 |             Ok(EncodedPage {
6502 |                 num_rows,
6503 |                 column_idx,
6504 |                 data,
6505 |                 description: PageEncoding::Structural(description),
6506 |                 row_number,
6507 |             })
6508 |         } else {
6509 |             let description = ProtobufUtils21::miniblock_layout(
6510 |                 compressed_rep.map(|cr| cr.compression),
6511 |                 compressed_def.map(|cd| cd.compression),
6512 |                 value_encoding,
6513 |                 rep_index_depth,
6514 |                 serialized.num_buffers,
6515 |                 None,
6516 |                 &repdef.def_meaning,
6517 |                 num_items,
6518 |                 has_large_chunk,
6519 |             );
6520 | 
6521 |             if let Some(rep_index) = rep_index {
6522 |                 let view = rep_index.borrow_to_typed_slice::<u64>();
6523 |                 let total = view.as_chunks::<2>().0.iter().map(|c| c[0]).sum::<u64>();
6524 |                 debug_assert_eq!(total, num_rows);
6525 | 
6526 |                 data.push(rep_index);
6527 |             }
6528 | 
6529 |             Ok(EncodedPage {
6530 |                 num_rows,
6531 |                 column_idx,
6532 |                 data,
6533 |                 description: PageEncoding::Structural(description),
6534 |                 row_number,
6535 |             })
6536 |         }
6537 |     }
